<?php
session_start(); require_once '../config/database.php'; require_once '../includes/functions.php'; requireRole('ADMIN');
$error=''; $success=$_GET['success']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='save'){
  $id=(int)($_POST['id']??0); $number=trim($_POST['bus_number']??''); $name=trim($_POST['bus_name']??''); $grade=$_POST['vehicle_grade']??'Level 1'; $seats=max(1,(int)($_POST['total_seats']??20)); $plate=trim($_POST['license_plate']??''); $status=$_POST['status']??'active';
  if(!$number||!$name){$error='Bus number and bus name are required.';} else if($id){$s=$conn->prepare('UPDATE buses SET bus_number=?,bus_name=?,vehicle_grade=?,total_seats=?,license_plate=?,status=? WHERE id=?');$s->bind_param('sssissi',$number,$name,$grade,$seats,$plate,$status,$id);$ok=$s->execute();} else {$s=$conn->prepare('INSERT INTO buses(bus_number,bus_name,total_seats,vehicle_grade,license_plate,status) VALUES(?,?,?,?,?,?)');$s->bind_param('ssisss',$number,$name,$seats,$grade,$plate,$status);$ok=$s->execute();if($ok){$id=$conn->insert_id;for($n=1;$n<=$seats;$n++){ $row=(int)ceil($n/4);$col=(($n-1)%4)+1;$seat=chr(64+$row).$col;$q=$conn->prepare('INSERT INTO seats(bus_id,seat_number,row_number,column_number) VALUES(?,?,?,?)');$q->bind_param('isii',$id,$seat,$row,$col);$q->execute();}}}
  if(isset($ok)&&$ok){logAudit($conn,$_SESSION['user_id'],$id?'BUS_UPDATED':'BUS_CREATED','bus',$id);header('Location: buses.php?success='.urlencode($id?'Bus updated successfully.':'Bus added successfully.'));exit;} if(!$error)$error=$s->error;
 }
 if($action==='delete'){ $id=(int)$_POST['id'];$s=$conn->prepare('UPDATE buses SET status="inactive" WHERE id=?');$s->bind_param('i',$id);if($s->execute())$success='Bus deactivated successfully.'; }
}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM buses WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}
$buses=$conn->query('SELECT b.*,COUNT(s.id) seat_count FROM buses b LEFT JOIN seats s ON s.bus_id=b.id GROUP BY b.id ORDER BY b.created_at DESC')->fetch_all(MYSQLI_ASSOC);
function nav(){echo '<nav class="navbar navbar-dark navbar-custom sticky-top"><div class="container-fluid"><a class="navbar-brand" href="dashboard.php"><i class="fas fa-bus me-2"></i>SafeWay Admin</a><div class="d-flex align-items-center gap-3"><span class="text-white d-none d-md-inline">'.htmlspecialchars($_SESSION['full_name']).'</span><a class="btn btn-sm btn-light" href="../logout.php">Logout</a></div></div></nav><div class="container-fluid"><div class="row"><aside class="col-lg-2 admin-sidebar py-3"><a href="dashboard.php"><i class="fas fa-chart-line"></i> Dashboard</a><a class="active" href="buses.php"><i class="fas fa-bus"></i> Buses</a><a href="routes.php"><i class="fas fa-route"></i> Routes</a><a href="trips.php"><i class="fas fa-calendar"></i> Trips</a><a href="bookings.php"><i class="fas fa-ticket"></i> Bookings</a><a href="users.php"><i class="fas fa-users"></i> Users</a><a href="reports.php"><i class="fas fa-chart-pie"></i> Reports</a><a href="settings.php"><i class="fas fa-gear"></i> Settings</a></aside><main class="col-lg-10 p-3 p-md-4">';}
function endnav(){echo '</main></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buses | SafeWay</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="../assets/css/modern.css"><style>.admin-sidebar{min-height:calc(100vh - 70px);background:#fff;border-right:1px solid #e2e8f0}.admin-sidebar a{display:block;padding:.8rem 1rem;border-radius:10px;color:#475569;font-weight:600;margin:.2rem 0}.admin-sidebar a:hover,.admin-sidebar a.active{background:#eff6ff;color:#2563eb}.admin-sidebar i{width:24px}.page-card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;box-shadow:0 10px 30px rgba(15,23,42,.06)}</style></head><body><?php nav(); ?><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><span class="text-primary fw-bold small text-uppercase">Fleet</span><h1 class="h2 mb-1">Bus management</h1><p class="text-secondary mb-0">Manage vehicles and automatically provision seats.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#busModal"><i class="fas fa-plus me-2"></i>Add bus</button></div><?php if($error):?><div class="alert alert-danger"><?php echo htmlspecialchars($error);?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?php echo htmlspecialchars($success);?></div><?php endif;?><div class="page-card p-3 p-md-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Bus</th><th>Grade</th><th>Seats</th><th>Plate</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($buses as $b):?><tr><td><strong><?php echo htmlspecialchars($b['bus_number']);?></strong><div class="small text-secondary"><?php echo htmlspecialchars($b['bus_name']);?></div></td><td><?php echo htmlspecialchars($b['vehicle_grade']);?></td><td><?php echo (int)$b['total_seats'];?> <span class="small text-secondary">configured</span></td><td><?php echo htmlspecialchars($b['license_plate']?:'—');?></td><td><span class="badge <?php echo $b['status']==='active'?'bg-success':'bg-secondary';?>"><?php echo htmlspecialchars($b['status']);?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="?edit=<?php echo $b['id'];?>"><i class="fas fa-pen"></i></a><form class="d-inline" method="post" onsubmit="return confirm('Deactivate this bus?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo $b['id'];?>"><button class="btn btn-sm btn-outline-danger"><i class="fas fa-ban"></i></button></form></td></tr><?php endforeach;if(!$buses):?><tr><td colspan="6" class="text-center py-5 text-secondary">No buses yet.</td></tr><?php endif;?></tbody></table></div></div><?php endnav();?><div class="modal fade" id="busModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title"><?php echo $edit?'Edit bus':'Add bus';?></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Bus number</label><input class="form-control" name="bus_number" required value="<?php echo htmlspecialchars($edit['bus_number']??'');?>"></div><div class="col-md-6"><label class="form-label">Bus name</label><input class="form-control" name="bus_name" required value="<?php echo htmlspecialchars($edit['bus_name']??'');?>"></div><div class="col-md-6"><label class="form-label">Vehicle grade</label><select class="form-select" name="vehicle_grade"><?php foreach(['Level 1','Level 2','Level 3','VIP'] as $g):?><option <?php echo (($edit['vehicle_grade']??'Level 1')===$g)?'selected':'';?>><?php echo $g;?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Total seats</label><input class="form-control" type="number" min="1" max="100" name="total_seats" required value="<?php echo (int)($edit['total_seats']??20);?>"></div><div class="col-md-6"><label class="form-label">License plate</label><input class="form-control" name="license_plate" value="<?php echo htmlspecialchars($edit['license_plate']??'');?>"></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','maintenance','inactive'] as $s):?><option <?php echo (($edit['status']??'active')===$s)?'selected':'';?>><?php echo $s;?></option><?php endforeach;?></select></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save bus</button></div></form></div></div></div><?php if($edit):?><script>new bootstrap.Modal('#busModal').show()</script><?php endif;?></body></html>